// Generated from src/registry/sources/control-ui/recipes/skeleton.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const skeletonKnobs = [
  "--cui-skeleton-radius",
  "--cui-skeleton-background",
  "--cui-skeleton-background-image",
  "--cui-skeleton-highlight-background",
  "--cui-skeleton-animation-duration",
  "--cui-skeleton-easing",
  "--cui-skeleton-pulse-opacity",
] as const;
export type SkeletonKnobStyle = Partial<Record<(typeof skeletonKnobs)[number], string>>;

@layer components {
  :where([data-control-family="skeleton"][data-slot="root"]) {
    --cui-skeleton-radius: var(--radius-control);
    --cui-skeleton-background: var(--muted);
    --cui-skeleton-background-image: none;
    --cui-skeleton-highlight-background: oklch(from var(--foreground) l c h / 0.06);
    --cui-skeleton-animation-duration: calc(var(--duration-slow) * 5);
    --cui-skeleton-easing: var(--ease-standard);
    --cui-skeleton-pulse-opacity: 0.5;
    position: relative;
    overflow: hidden;
    isolation: isolate;
    border-radius: var(--cui-skeleton-radius);
    background-color: var(--cui-skeleton-background);
    background-image: var(--cui-skeleton-background-image);
  }

  :where([data-control-family="skeleton"][data-slot="root"][data-variant="shimmer"])::after {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    background-image: linear-gradient(90deg, transparent, var(--cui-skeleton-highlight-background), transparent);
    transform: translateX(-100%);
    animation: cui-skeleton-shimmer var(--cui-skeleton-animation-duration) var(--cui-skeleton-easing) infinite;
  }

  :where([data-control-family="skeleton"][data-slot="root"][data-variant="pulse"]) {
    animation: cui-skeleton-pulse var(--cui-skeleton-animation-duration) var(--cui-skeleton-easing) infinite;
  }

  :where([data-control-family="skeleton"][data-slot="root"][data-variant="none"]) {
    animation: none;
  }

  @media (prefers-reduced-motion: reduce) {
    :where([data-control-family="skeleton"][data-slot="root"]),
    :where([data-control-family="skeleton"][data-slot="root"])::after {
      animation: none;
    }
  }

  :where([data-motion="reduced"] [data-control-family="skeleton"][data-slot="root"]),
  :where([data-motion="reduced"] [data-control-family="skeleton"][data-slot="root"])::after {
    animation: none;
  }
}

@keyframes cui-skeleton-shimmer {
  to {
    transform: translateX(100%);
  }
}

@keyframes cui-skeleton-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: var(--cui-skeleton-pulse-opacity);
  }
}

@property --cui-skeleton-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-skeleton-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-skeleton-background-image {
  syntax: "*";
  inherits: true;
  initial-value: none;
}

@property --cui-skeleton-highlight-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-skeleton-animation-duration {
  syntax: "<time>";
  inherits: true;
  initial-value: 0s;
}

@property --cui-skeleton-easing {
  syntax: "*";
  inherits: true;
  initial-value: ease;
}

@property --cui-skeleton-pulse-opacity {
  syntax: "<number>";
  inherits: true;
  initial-value: 0.5;
}

import type { ComponentProps, CSSProperties } from "react";
import type { SkeletonKnobStyle } from "@/components/control-ui/knob-contracts/skeleton-knobs";

export const skeletonVariants = ["shimmer", "pulse", "none"] as const;

export type SkeletonVariant = (typeof skeletonVariants)[number];

export type SkeletonProps = Omit<ComponentProps<"div">, "style"> & {
  style?: CSSProperties & SkeletonKnobStyle;
  variant?: SkeletonVariant;
};

export function Skeleton({ variant = "shimmer", className, ...props }: SkeletonProps) {
  return (
    <div
      aria-hidden="true"
      data-control-ui="skeleton"
      data-control-family="skeleton"
      data-slot="root"
      data-variant={variant}
      className={className}
      {...props}
    />
  );
}
